                  (Z_to_bv 64 n) s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (Z_to_bv 64 refill_entry) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 64, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
